SELECT 

 WHERE G.PROG_KIND_CD = 'S001'

  AND G.PROG_DT = #{targetDt}


  AND G.PROG_DT >= #{searchFrom}


  AND G.PROG_DT <= #{searchTo}


  AND S.CASE_NO LIKE '%' || #{searchCaseNo} || '%'


  AND G.DYPR_KIND_CD = #{searchDyprKind}


  AND S.INSTANCE_CD = #{searchInstance}

 ORDER BY G.PROG_DT, G.PROG_TM, G.PROG_ID
